<?php
session_start(); require_once '../middleware/student.php'; require_once '../config/database.php'; require_once '../helpers/internship_pdf_helper.php'; require_once '../helpers/document_download_access_helper.php'; require_once '../helpers/alert_response_helper.php';
$documentId=(int)($_GET['document']??0);
$stmt=$pdo->prepare('SELECT ip.*,ic.academic_year,ic.semester,ic.start_date,ic.end_date,ia.request_date,ia.status AS application_status,doc.document_status,doc.document_id,s.student_number,s.firstname,s.lastname,p.prefix_short,d.department_name,f.faculty_name,CONCAT(COALESCE(ap.prefix_short,ap.prefix_name,""),ae.firstname," ",ae.lastname) AS advisor_name, (SELECT CONCAT(COALESCE(cp.prefix_short,cp.prefix_name,""),ce.firstname," ",ce.lastname) FROM employee ce LEFT JOIN prefixes cp ON cp.prefix_id=ce.prefix_id JOIN employee_position cep ON cep.employee_id=ce.employee_id JOIN positions cpos ON cpos.position_id=cep.position_id WHERE ce.department_id=d.department_id AND cpos.position_name="อาจารย์ประสานงานฝึกประสบการณ์วิชาชีพ" ORDER BY ce.employee_id LIMIT 1) AS coordinator_name FROM internship_application ia JOIN documents doc ON doc.document_id=ia.document_id JOIN internship_profile ip ON ip.internship_profile_id=ia.internship_profile_id JOIN internship_calendar ic ON ic.calendar_id=ip.calendar_id JOIN student s ON s.student_id=ip.student_id LEFT JOIN prefixes p ON p.prefix_id=s.prefix_id LEFT JOIN group_class g ON g.group_id=s.group_id LEFT JOIN employee ae ON ae.employee_id=g.advisor_employee_id LEFT JOIN prefixes ap ON ap.prefix_id=ae.prefix_id LEFT JOIN department d ON d.department_id=g.department_id LEFT JOIN faculty f ON f.faculty_id=d.faculty_id WHERE s.user_id=? AND (?=0 OR doc.document_id=?) ORDER BY doc.document_id DESC LIMIT 1');
$stmt->execute([$_SESSION['user_id'],$documentId,$documentId]); $row=$stmt->fetch(PDO::FETCH_ASSOC); if(!$row){renderSweetAlertResponse('ไม่พบเอกสาร','ไม่พบเอกสารที่ต้องการพิมพ์ กรุณากลับไปตรวจสอบรายการอีกครั้ง','error','internship_submissions.php',404);}
if(!studentCanDownloadDocument('INTERNSHIP_INFO',(string)$row['document_status'],(string)$row['application_status'])){renderSweetAlertResponse('ยังพิมพ์เอกสารไม่ได้','เอกสารจะพิมพ์ได้เมื่ออยู่ในขั้นลงชื่อหรือผ่านการพิจารณาแล้ว','warning','internship_submissions.php',403);}
$pdf=createInternshipApplicationPdf($row); $pdf->Output('RMUTI_Pro-Ex_02-'.$row['student_number'].'.pdf','D');
